args.content:
function escapeHtml(value) {
  return String(value)
    .replaceAll("&", "&amp;")
    .replaceAll("<", "&lt;")
    .replaceAll(">", "&gt;")
    .replaceAll('"', "&quot;")
    .replaceAll("'", "&#39;");
}

function layout({ title, description, body }) {
  const desc = description ? `<meta name="description" content="${escapeHtml(description)}">` : "";
  return `<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width, initial-scale=1">
  <title>${escapeHtml(title)}</title>
  ${desc}
  <style>
    :root {
      color-scheme: light;
      --bg: #f3eee6;
      --card: #fffaf4;
      --ink: #241c16;
      --muted: #6f6258;
      --line: #e3d5c6;
      --clay: #8c3d2f;
      --moss: #2f6f4e;
    }
    * { box-sizing: border-box; }
    body {
      margin: 0;
      background: var(--bg);
      color: var(--ink);
      font: 18px/1.5 "Iowan Old Style", "Palatino Linotype", Palatino, "Book Antiqua", Georgia, serif;
    }
    main {
      max-width: 40rem;
      margin: 0 auto;
      padding: 2.5rem 1.25rem 4rem;
    }
    h1, h2 { font-weight: 500; }
    h1 { font-size: 2.4rem; line-height: 1.15; margin: 0; }
    h2 { font-size: 1.3rem; margin: 2rem 0 0.75rem; }
    a { color: inherit; }
    .lede, .meta, .empty { color: var(--muted); }
    .lede { margin: 0.4rem 0 0; }
    .back { margin: 0 0 1.25rem; }
    form, .book {
      background: var(--card);
      border: 1px solid var(--line);
      border-radius: 12px;
    }
    form { padding: 1rem 1.1rem 1.15rem; }
    form h2 { margin: 0 0 0.9rem; }
    label { display: block; margin-bottom: 0.8rem; }
    input, textarea {
      display: block;
      width: 100%;
      margin-top: 0.3rem;
      padding: 0.5rem 0.6rem;
      border: 1px solid var(--line);
      border-radius: 8px;
      background: #fff;
      color: inherit;
      font: inherit;
    }
    textarea { min-height: 7rem; resize: vertical; }
    button, .button {
      font: inherit;
      border-radius: 999px;
      padding: 0.4rem 0.9rem;
      cursor: pointer;
    }
    button {
      background: var(--ink);
      color: #fffaf4;
      border: 0;
    }
    button.secondary {
      background: transparent;
      color: var(--clay);
      border: 1px solid var(--clay);
    }
    button:hover, .book-link:hover .title { text-decoration: underline; }
    :focus-visible { outline: 2px solid var(--clay); outline-offset: 2px; }
    .shelf { list-style: none; padding: 0; margin: 0; display: grid; gap: 0.75rem; }
    .book {
      display: flex;
      justify-content: space-between;
      align-items: center;
      gap: 1rem;
      flex-wrap: wrap;
      padding: 0.85rem 1rem;
    }
    #reading .book { border-left: 4px solid var(--clay); }
    #finished .book { border-left: 4px solid var(--moss); }
    .book-link { text-decoration: none; }
    .title { display: block; font-size: 1.15rem; }
    .error {
      margin: 0 0 1rem;
      padding: 0.6rem 0.75rem;
      border-radius: 8px;
      background: #f8e8e3;
      color: var(--clay);
    }
    .status {
      display: inline-block;
      margin: 0.4rem 0 0;
      font-size: 0.85rem;
      letter-spacing: 0.04em;
      text-transform: uppercase;
    }
    .status.reading { color: var(--clay); }
    .status.finished { color: var(--moss); }
    .notes { white-space: pre-wrap; margin: 0.4rem 0 1.25rem; }
    .share { margin-top: 1.5rem; }
    .share input { font-size: 0.95rem; }
  </style>
</head>
<body>
  <main>
    ${body}
  </main>
</body>
</html>`;
}

function bookItem(book, { finish }) {
  const action = finish
    ? `<form method="post" action="/books/${escapeHtml(book.id)}/finish">
        <input type="hidden" name="next" value="/">
        <button class="secondary" type="submit" aria-label="Mark ${escapeHtml(book.title)} as finished">Mark as finished</button>
      </form>`
    : "";
  return `<li class="book">
    <a class="book-link" href="/books/${escapeHtml(book.id)}">
      <span class="title">${escapeHtml(book.title)}</span>
      <span class="meta">${escapeHtml(book.author)}</span>
    </a>
    ${action}
  </li>`;
}

function shelf(books, { finish }) {
  if (books.length === 0) return "";
  return `<ul class="shelf">${books.map((book) => bookItem(book, { finish })).join("")}</ul>`;
}

export function homePage({ reading, finished, error = "", form = {} }) {
  const errorHtml = error ? `<p class="error" role="alert">${escapeHtml(error)}</p>` : "";
  const readingList = reading.length
    ? shelf(reading, { finish: true })
    : `<p class="empty">No books in progress.</p>`;
  const finishedList = finished.length
    ? shelf(finished, { finish: false })
    : `<p class="empty">No finished books yet.</p>`;

  return layout({
    title: "Books",
    description: "Books you are reading and books you have finished.",
    body: `<h1>Books</h1>
    <p class="lede">What you're reading, and what you've finished.</p>
    <section id="reading">
      <h2>Currently reading</h2>
      ${readingList}
    </section>
    <section id="finished">
      <h2>Finished</h2>
      ${finishedList}
    </section>
    <form id="add-book" method="post" action="/books" accept-charset="utf-8">
      <h2>Add a book</h2>
      ${errorHtml}
      <label for="title">Title
        <input id="title" name="title" required maxlength="200" value="${escapeHtml(form.title ?? "")}">
      </label>
      <label for="author">Author
        <input id="author" name="author" required maxlength="200" value="${escapeHtml(form.author ?? "")}">
      </label>
      <label for="notes">Notes
        <textarea id="notes" name="notes" maxlength="4000">${escapeHtml(form.notes ?? "")}</textarea>
      </label>
      <button type="submit">Add book</button>
    </form>`,
  });
}

export function bookPage(book, { shareUrl }) {
  const finished = book.status === "finished";
  const notes = book.notes
    ? `<div class="notes">${escapeHtml(book.notes)}</div>`
    : `<p class="notes empty">No notes yet.</p>`;
  const finish = finished
    ? ""
    : `<form method="post" action="/books/${escapeHtml(book.id)}/finish">
        <input type="hidden" name="next" value="/books/${escapeHtml(book.id)}">
        <button type="submit">Mark as finished</button>
      </form>`;

  return layout({
    title: `${book.title} · Books`,
    description: `${book.title} by ${book.author}`,
    body: `<p class="back"><a href="/">All books</a></p>
    <h1>${escapeHtml(book.title)}</h1>
    <p class="meta">by ${escapeHtml(book.author)}</p>
    <p class="status ${finished ? "finished" : "reading"}">${finished ? "Finished" : "Reading"}</p>
    <h2>Notes</h2>
    ${notes}
    ${finish}
    <form class="share">
      <label for="share-link">Link to this book
        <input id="share-link" readonly value="${escapeHtml(shareUrl)}" aria-label="Link to this book">
      </label>
    </form>
    <p class="meta">Copy that address to send someone this book.</p>`,
  });
}

export function notFoundPage() {
  return layout({
    title: "Book not found",
    body: `<h1>Book not found</h1>
    <p class="lede">That link doesn't match a book on this shelf.</p>
    <p><a href="/">All books</a></p>`,
  });
}

