import { createServer } from "node:http";
import { mkdtemp, rm } from "node:fs/promises";
import { once } from "node:events";
import { tmpdir } from "node:os";
import path from "node:path";
import { afterEach, beforeEach, expect, test } from "vitest";
import { createHandler } from "../src/app.js";
import { createStore } from "../src/store.js";

let dir;
let server;
let base;

beforeEach(async () => {
  dir = await mkdtemp(path.join(tmpdir(), "books-app-"));
  const store = createStore(path.join(dir, "books.json"));
  server = createServer(createHandler(store));
  server.listen(0, "127.0.0.1");
  await once(server, "listening");
  base = `http://127.0.0.1:${server.address().port}`;
});

afterEach(async () => {
  server.close();
  if (typeof server.closeAllConnections === "function") server.closeAllConnections();
  await once(server, "close");
  await rm(dir, { recursive: true, force: true });
});

function section(html, id) {
  const start = html.indexOf(`<section id="${id}">`);
  const end = html.indexOf("</section>", start);
  return html.slice(start, end);
}

async function addBook({ title, author, notes }) {
  return fetch(`${base}/books`, {
    method: "POST",
    body: new URLSearchParams({ title, author, notes }),
  });
}

test("home shows currently reading and finished, including when both are empty", async () => {
  const response = await fetch(`${base}/`);
  expect(response.status).toBe(200);
  const html = await response.text();
  expect(section(html, "reading")).toContain("Currently reading");
  expect(section(html, "reading")).toContain("No books in progress.");
  expect(section(html, "finished")).toContain("Finished");
  expect(section(html, "finished")).toContain("No finished books yet.");
  expect(html).toContain("Add a book");
});

test("adds a book from the form, links to it, and shows title, author, and notes", async () => {
  const created = await addBook({
    title: "Kindred",
    author: "Octavia Butler",
    notes: "Notes with <tags> & quotes",
  });
  expect(created.redirected).toBe(true);
  expect(created.status).toBe(200);

  const home = await created.text();
  const reading = section(home, "reading");
  const match = reading.match(/href="\/books\/([A-Za-z0-9_-]+)"/);
  expect(match).not.toBeNull();
  expect(reading).toContain("Kindred");
  expect(reading).toContain("Octavia Butler");
  expect(section(home, "finished")).not.toContain("Kindred");
  expect(reading).toContain("Mark as finished");

  const detail = await fetch(`${base}/books/${match[1]}`);
  expect(detail.status).toBe(200);
  const page = await detail.text();
  expect(page).toContain("Kindred");
  expect(page).toContain("Octavia Butler");
  expect(page).toContain("Notes with &lt;tags&gt; &amp; quotes");
  expect(page).not.toContain("<tags>");
  expect(page).toContain(`${base}/books/${match[1]}`);
  expect(page).toContain("Copy that address to send someone this book.");
});

test("marks a book finished from the list and keeps it out of currently reading", async () => {
  await addBook({ title: "Piranesi", author: "Susanna Clarke", notes: "halls" });
  const home = await fetch(`${base}/`).then((response) => response.text());
  const id = section(home, "reading").match(/href="\/books\/([A-Za-z0-9_-]+)"/)[1];

  const finished = await fetch(`${base}/books/${id}/finish`, {
    method: "POST",
    body: new URLSearchParams({ next: "/" }),
  });
  expect(finished.redirected).toBe(true);
  const after = await finished.text();
  expect(section(after, "reading")).not.toContain("Piranesi");
  expect(section(after, "finished")).toContain("Piranesi");
  expect(section(after, "finished")).toContain(`/books/${id}`);
});

test("a book link still works after the process reloads the same JSON file", async () => {
  await addBook({ title: "Circe", author: "Madeline Miller", notes: "witchcraft" });
  const home = await fetch(`${base}/`).then((response) => response.text());
  const id = section(home, "reading").match(/href="\/books\/([A-Za-z0-9_-]+)"/)[1];
  await fetch(`${base}/books/${id}/finish`, {
    method: "POST",
    body: new URLSearchParams({ next: `/books/${id}` }),
  });

  const reloaded = createStore(path.join(dir, "books.json"));
  const book = await reloaded.get(id);
  expect(book).toMatchObject({
    title: "Circe",
    author: "Madeline Miller",
    notes: "witchcraft",
    status: "finished",
  });
});

test("rejects an incomplete form and does not save the book", async () => {
  const response = await fetch(`${base}/books`, {
    method: "POST",
    body: new URLSearchParams({ title: "", author: "Nobody", notes: "nope" }),
  });
  expect(response.status).toBe(400);
  const html = await response.text();
  expect(html).toContain("Title and author are required.");
  expect(html).toContain("Nobody");
  expect(section(html, "reading")).not.toContain("Nobody");
});

test("unknown book links return not found", async () => {
  const response = await fetch(`${base}/books/missing-book`);
  expect(response.status).toBe(404);
  expect(await response.text()).toContain("Book not found");
});

