  expect(page).toContain("Copy that address to send someone this book.");
});

test("marks a book finished from the list and keeps it out of currently reading", async () => {
  await addBook({ title: "Piranesi", author: "Susanna Clarke", notes: "halls" });
  const home = await fetch(`${base}/`).then((response) => response.text());
  const id = section(home, "reading").match(/href="\/books\/([A-Za-z0-9_-]+)"/)[1];

  const finished = await fetch(`${base}/books/${id}/finish`, {
    method: "POST",
    body: new URLSearchParams({ next: "/" }),
  });
  expect(finished.redirected).toBe(true);
  const after = await finished.text();
  expect(section(after, "reading")).not.toContain("Piranesi");
  expect(section(after, "finished")).toContain("Piranesi");
  expect(section(after, "finished")).toContain(`/books/${id}`);
});

test("a book link still works after the process reloads the same JSON file", async () => {
  await addBook({ title: "Circe", author: "Madeline Miller", notes: "witchcraft" });
  const home = await fetch(`${base}/`).then((response) => response.text());
  const id = section(home, "reading").match(/href="\/books\/([A-Za-z0-9_-]+)"/)[1];
  await fetch(`${base}/books/${id}/finish`, {
    method: "POST",
    body: new URLSearchParams({ next: `/books/${id}` }),
  });

  const reloaded = createStore(path.join(dir, "books.json"));
  const book = await reloaded.get(id);
  expect(book).toMatchObject({
    title: "Circe",
    author: "Madeline Miller",
    notes: "witchcraft",
    status: "finished",
  });
});

test("rejects an incomplete form and does not save the book", async () => {
  const response = await fetch(`${base}/books`, {
    method: "POST",
    body: new URLSearchParams({ title: "", author: "Nobody", notes: "nope" }),
  });
  expect(response.status).toBe(400);
  const html = await response.text();
  expect(html).toContain("Title and author are required.");
  expect(html).toContain("Nobody");
  expect(section(html, "reading")).not.toContain("Nobody");
});

test("unknown book links return not found", async () => {
  const response = await fetch(`${base}/books/missing-book`);
  expect(response.status).toBe(404);
  expect(await response.text()).toContain("Book not found");
});
"}

