import { randomBytes } from "node:crypto";
import { mkdir, readFile, rename, writeFile } from "node:fs/promises";
import path from "node:path";

const LIMITS = {
  title: 200,
  author: 200,
  notes: 4000,
};

export class StoreError extends Error {
  constructor(message) {
    super(message);
    this.name = "StoreError";
  }
}

export function validateBookInput(input) {
  const title = String(input?.title ?? "").trim();
  const author = String(input?.author ?? "").trim();
  const notes = String(input?.notes ?? "").trim();

  if (!title || !author) {
    return { error: "Title and author are required." };
  }
  if (title.length > LIMITS.title || author.length > LIMITS.author) {
    return { error: "Title and author must be 200 characters or fewer." };
  }
  if (notes.length > LIMITS.notes) {
    return { error: "Notes must be 4000 characters or fewer." };
  }
  return { value: { title, author, notes } };
}

function normalize(book) {
  return {
    id: String(book.id),
    title: String(book.title ?? ""),
    author: String(book.author ?? ""),
    notes: String(book.notes ?? ""),
    status: book.status === "finished" ? "finished" : "reading",
    addedAt: book.addedAt ?? null,
    finishedAt: book.finishedAt ?? null,
  };
}

function parseStore(text) {
  if (!text.trim()) return { books: [] };
  const data = JSON.parse(text);
  if (!data || typeof data !== "object" || !Array.isArray(data.books)) {
    throw new StoreError("books.json must be an object with a books array.");
  }
  return {
    books: data.books
      .filter((book) => book && typeof book === "object" && book.id)
      .map(normalize),
  };
}

function newId(books) {
  const ids = new Set(books.map((book) => book.id));
  let id = "";
  do {
    id = randomBytes(6).toString("base64url");
  } while (ids.has(id));
  return id;
}

export function createStore(filePath) {
  const resolved = path.resolve(filePath);
  let tail = Promise.resolve();

  function lock(fn) {
    const run = tail.then(fn, fn);
    tail = run.then(
      () => {},
      () => {},
    );
    return run;
  }

  async function read() {
    try {
      return parseStore(await readFile(resolved, "utf8"));
    } catch (error) {
      if (error && error.code === "ENOENT") return { books: [] };
      throw error;
    }
  }

  async function write(data) {
    await mkdir(path.dirname(resolved), { recursive: true });
    const tmp = `${resolved}.${process.pid}.tmp`;
    await writeFile(tmp, `${JSON.stringify(data, null, 2)}\n`, "utf8");
    // Rename is atomic on the same filesystem, so a restart never reads a half-written file.
    await rename(tmp, resolved);
  }

  return {
    filePath: resolved,
    list() {
      return lock(async () => (await read()).books);
    },
    get(id) {
      return lock(async () => (await read()).books.find((book) => book.id === id) ?? null);
    },
    add(input) {
      return lock(async () => {
        const parsed = validateBookInput(input);
        if (parsed.error) throw new StoreError(parsed.error);
        const data = await read();
        const book = {
          id: newId(data.books),
          ...parsed.value,
          status: "reading",
          addedAt: new Date().toISOString(),
          finishedAt: null,
        };
        data.books.push(book);
        await write(data);
        return book;
      });
    },
    finish(id) {
      return lock(async () => {
        const data = await read();
        const book = data.books.find((item) => item.id === id);
        if (!book) return null;
        if (book.status !== "finished") {
          book.status = "finished";
          book.finishedAt = new Date().toISOString();
          await write(data);
        }
        return book;
      });
    },
  };
}

import { createServer } from "node:http";
import { createHandler } from "./src/app.js";
import { createStore } from "./src/store.js";

const port = Number(process.env.PORT) || 3000;
const host = process.env.HOST || "127.0.0.1";
const file = process.env.BOOKS_FILE || "books.json";
const store = createStore(file);
const server = createServer(createHandler(store));

server.listen(port, host, () => {
  console.log(`Book tracker running at http://${host}:${port}`);
  console.log(`Saving books to ${store.filePath}`);
});

import { mkdtemp, readFile, rm } from "node:fs/promises";
import { tmpdir } from "node:os";
import path from "node:path";
import { afterEach, beforeEach, expect, test } from "vitest";
import { createStore } from "../src/store.js";

let dir;

beforeEach(async () => {
  dir = await mkdtemp(path.join(tmpdir(), "books-"));
});

afterEach(async () => {
  await rm(dir, { recursive: true, force: true });
});

function file() {
  return path.join(dir, "books.json");
}

test("starts empty when the file does not exist yet", async () => {
  const store = createStore(file());
  await expect(store.list()).resolves.toEqual([]);
});

test("saves added books to the JSON file and keeps them after a new store is opened", async () => {
  const store = createStore(file());
  const added = await store.add({
    title: "  The Left Hand of Darkness  ",
    author: " Ursula K. Le Guin ",
    notes: " Cold planet, warm book. ",
  });

  expect(added.status).toBe("reading");
  expect(added.title).toBe("The Left Hand of Darkness");
  expect(added.notes).toBe("Cold planet, warm book.");

  const restarted = createStore(file());
  const books = await restarted.list();
  expect(books).toHaveLength(1);
  expect(books[0]).toMatchObject({
    id: added.id,
    title: "The Left Hand of Darkness",
    author: "Ursula K. Le Guin",
    notes: "Cold planet, warm book.",
    status: "reading",
    finishedAt: null,
  });

  const raw = JSON.parse(await readFile(file(), "utf8"));
  expect(raw.books[0].title).toBe("The Left Hand of Darkness");
});

test("marks a book finished and keeps that after a restart", async () => {
  const store = createStore(file());
  const added = await store.add({ title: "Dune", author: "Frank Herbert", notes: "spice" });
  const finished = await store.finish(added.id);

  expect(finished.status).toBe("finished");
  expect(finished.finishedAt).toEqual(expect.any(String));

  const restarted = createStore(file());
  await expect(restarted.get(added.id)).resolves.toMatchObject({
    status: "finished",
    notes: "spice",
  });
  const again = await restarted.finish(added.id);
  expect(again.finishedAt).toBe(finished.finishedAt);
});

test("returns null when finishing or loading an unknown book", async () => {
  const store = createStore(file());
  await expect(store.finish("missing")).resolves.toBeNull();
  await expect(store.get("missing")).resolves.toBeNull();
});

test("rejects a book without a title or author", async () => {
  const store = createStore(file());
  await expect(store.add({ title: "  ", author: "Someone", notes: "" })).rejects.toThrow(
    /title and author/i,
  );
  await expect(store.list()).resolves.toEqual([]);
});

